206	type ReviewConfig struct {
207		// Skills is the list of slash-prefixed skill invocations configured
208		// for this agent. May be empty when Prompt carries the full request.
209		Skills []string `json:"skills,omitempty"`
210	
211		// Prompt, when non-empty, carries saved review instructions. When
212		// Skills is non-empty it is appended after the selected skills; when
213		// Skills is empty it is the full prompt for prompt-only review configs.
214		Prompt string `json:"prompt,omitempty"`
215	}
