282	// LoadFromFile loads settings from a specific file path without merging local overrides.
283	// Returns default settings if the file doesn't exist.
284	// Use this when you need to display individual settings files separately.
285	func LoadFromFile(filePath string) (*EntireSettings, error) {
286		return loadFromFile(filePath)
287	}
