289	// LoadFromBytes parses settings from raw JSON bytes without merging local overrides.
290	// Use this when you have settings content from a non-file source (e.g., git show).
291	func LoadFromBytes(data []byte) (*EntireSettings, error) {
292		s := &EntireSettings{Enabled: true}
293		dec := json.NewDecoder(bytes.NewReader(data))
294		dec.DisallowUnknownFields()
295		if err := dec.Decode(s); err != nil {
296			return nil, fmt.Errorf("parsing settings: %w", err)
297		}
298		return s, nil
299	}
