301	// loadFromFile loads settings from a specific file path.
302	// Returns default settings if the file doesn't exist.
303	func loadFromFile(filePath string) (*EntireSettings, error) {
304		settings := &EntireSettings{
305			Enabled: true, // Default to enabled
306		}
307	
308		data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
309		if err != nil {
310			if os.IsNotExist(err) {
311				return settings, nil
312			}
313			return nil, fmt.Errorf("%w", err)
314		}
315	
316		dec := json.NewDecoder(bytes.NewReader(data))
317		dec.DisallowUnknownFields()
318		if err := dec.Decode(settings); err != nil {
319			return nil, fmt.Errorf("parsing settings file: %w", err)
320		}
321	
322		// Validate commit_linking if set
323		if settings.CommitLinking != "" && settings.CommitLinking != CommitLinkingAlways && settings.CommitLinking != CommitLinkingPrompt {
324			return nil, fmt.Errorf("invalid commit_linking value %q: must be %q or %q", settings.CommitLinking, CommitLinkingAlways, CommitLinkingPrompt)
325		}
326	
327		// SummaryGeneration is NOT validated here — individual files may
328		// legitimately contain only a model (provider comes from another file).
329		// Validation happens after merge in Load().
330	
331		return settings, nil
332	}
