334	// mergeJSON merges JSON data into existing settings.
335	// Only non-zero values from the JSON override existing settings.
336	func mergeJSON(settings *EntireSettings, data []byte) error {
337		// Validate that there are no unknown keys using strict decoding.
338		dec := json.NewDecoder(bytes.NewReader(data))
339		dec.DisallowUnknownFields()
340		var temp EntireSettings
341		if err := dec.Decode(&temp); err != nil {
342			return fmt.Errorf("parsing JSON: %w", err)
343		}
344	
345		// Parse into a map to check which fields are present.
346		var raw map[string]json.RawMessage
347		if err := json.Unmarshal(data, &raw); err != nil {
348			return fmt.Errorf("parsing JSON: %w", err)
349		}
350	
351		if err := mergeScalarFields(settings, raw); err != nil {
352			return err
353		}
354		if err := mergeStrategyOptions(settings, raw); err != nil {
355			return err
356		}
357		if err := mergeSummaryGeneration(settings, raw); err != nil {
358			return err
359		}
360		if err := mergeCommitLinking(settings, raw); err != nil {
361			return err
362		}
363	
364		// Merge redaction sub-fields if present (field-level, not wholesale replace).
365		if redactionRaw, ok := raw["redaction"]; ok {
366			if settings.Redaction == nil {
367				settings.Redaction = &RedactionSettings{}
368			}
369			if err := mergeRedaction(settings.Redaction, redactionRaw); err != nil {
370				return fmt.Errorf("parsing redaction field: %w", err)
371			}
372		}
373	
374		return nil
375	}
376	
377	// mergeScalarFields merges simple bool, *bool, string, and int fields from raw JSON.
378	func mergeScalarFields(settings *EntireSettings, raw map[string]json.RawMessage) error {
379		if err := mergeRawBool(raw, "enabled", &settings.Enabled); err != nil {
380			return err
381		}
382		if err := mergeRawBool(raw, "local_dev", &settings.LocalDev); err != nil {
383			return err
384		}
385		if err := mergeRawBool(raw, "absolute_git_hook_path", &settings.AbsoluteGitHookPath); err != nil {
386			return err
387		}
388		if err := mergeRawBool(raw, "external_agents", &settings.ExternalAgents); err != nil {
389			return err
390		}
391		if err := mergeRawBool(raw, "vercel", &settings.Vercel); err != nil {
392			return err
393		}
394		if err := mergeRawBoolPtr(raw, "telemetry", &settings.Telemetry); err != nil {
395			return err
396		}
397		if err := mergeRawBoolPtr(raw, "sign_checkpoint_commits", &settings.SignCheckpointCommits); err != nil {
398			return err
399		}
400		if err := mergeRawStringNonEmpty(raw, "log_level", &settings.LogLevel); err != nil {
401			return err
402		}
403		if err := mergeRawStringNonEmpty(raw, "review_fix_agent", &settings.ReviewFixAgent); err != nil {
404			return err
405		}
406		if err := mergeRawInt(raw, "summary_timeout_seconds", &settings.SummaryTimeoutSeconds); err != nil {
407			return err
408		}
409		return nil
410	}
411	
412	func mergeRawBool(raw map[string]json.RawMessage, key string, dst *bool) error {
413		v, ok := raw[key]
414		if !ok {
415			return nil
416		}
417		return unmarshalField(key, v, dst)
418	}
419	
420	func mergeRawBoolPtr(raw map[string]json.RawMessage, key string, dst **bool) error {
421		v, ok := raw[key]
422		if !ok {
423			return nil
424		}
425		var b bool
426		if err := unmarshalField(key, v, &b); err != nil {
427			return err
428		}
429		*dst = &b
430		return nil
431	}
432	
433	func mergeRawStringNonEmpty(raw map[string]json.RawMessage, key string, dst *string) error {
434		v, ok := raw[key]
435		if !ok {
436			return nil
437		}
438		var s string
439		if err := unmarshalField(key, v, &s); err != nil {
440			return err
441		}
442		if s != "" {
443			*dst = s
444		}
445		return nil
446	}
447	
448	func mergeRawInt(raw map[string]json.RawMessage, key string, dst *int) error {
449		v, ok := raw[key]
450		if !ok {
451			return nil
452		}
453		return unmarshalField(key, v, dst)
454	}
455	
456	func unmarshalField(key string, data json.RawMessage, dst any) error {
457		if err := json.Unmarshal(data, dst); err != nil {
458			return fmt.Errorf("parsing %s field: %w", key, err)
459		}
460		return nil
461	}
