463	func mergeStrategyOptions(settings *EntireSettings, raw map[string]json.RawMessage) error {
464		optionsRaw, ok := raw["strategy_options"]
465		if !ok {
466			return nil
467		}
468		var opts map[string]any
469		if err := unmarshalField("strategy_options", optionsRaw, &opts); err != nil {
470			return err
471		}
472		if settings.StrategyOptions == nil {
473			settings.StrategyOptions = opts
474		} else {
475			for k, v := range opts {
476				settings.StrategyOptions[k] = v
477			}
478		}
479		return nil
480	}
481	
482	func mergeSummaryGeneration(settings *EntireSettings, raw map[string]json.RawMessage) error {
483		summaryRaw, ok := raw["summary_generation"]
484		if !ok {
485			return nil
486		}
487		if settings.SummaryGeneration == nil {
488			settings.SummaryGeneration = &SummaryGenerationSettings{}
489		}
490	
491		var summaryFields map[string]json.RawMessage
492		if err := unmarshalField("summary_generation", summaryRaw, &summaryFields); err != nil {
493			return err
494		}
495	
496		_, modelInOverride := summaryFields["model"]
497	
498		if providerRaw, ok := summaryFields["provider"]; ok {
499			var provider string
500			if err := unmarshalField("summary_generation.provider", providerRaw, &provider); err != nil {
501				return err
502			}
503			// If the override switches providers without also setting a model,
504			// the base's model was tuned to the old provider and would likely
505			// cause a runtime failure when handed to the new one (e.g. codex
506			// rejecting "sonnet"). Clear it so the new provider falls back to
507			// its own default.
508			if provider != settings.SummaryGeneration.Provider && !modelInOverride {
509				settings.SummaryGeneration.Model = ""
510			}
511			settings.SummaryGeneration.Provider = provider
512		}
513	
514		if modelRaw, ok := summaryFields["model"]; ok {
515			var model string
516			if err := unmarshalField("summary_generation.model", modelRaw, &model); err != nil {
517				return err
518			}
519			settings.SummaryGeneration.Model = model
520		}
521		return nil
522	}
523	
524	func mergeCommitLinking(settings *EntireSettings, raw map[string]json.RawMessage) error {
525		commitLinkingRaw, ok := raw["commit_linking"]
526		if !ok {
527			return nil
528		}
529		var cl string
530		if err := unmarshalField("commit_linking", commitLinkingRaw, &cl); err != nil {
531			return err
532		}
533		if cl == "" {
534			return nil
535		}
536		switch cl {
537		case CommitLinkingAlways, CommitLinkingPrompt:
538			settings.CommitLinking = cl
539		default:
540			return fmt.Errorf("invalid commit_linking value %q: must be %q or %q", cl, CommitLinkingAlways, CommitLinkingPrompt)
541		}
542		return nil
543	}
