550			return fmt.Errorf("parsing redaction: %w", err)
551		}
552		if piiRaw, ok := raw["pii"]; ok {
553			if dst.PII == nil {
554				dst.PII = &PIISettings{}
555			}
556			if err := mergePIISettings(dst.PII, piiRaw); err != nil {
557				return err
558			}
