563	// mergePIISettings merges PII overrides into existing PIISettings.
564	// Only fields present in the override JSON are applied; missing fields
565	// are preserved from the base settings.
566	func mergePIISettings(dst *PIISettings, data json.RawMessage) error {
567		var raw map[string]json.RawMessage
568		if err := json.Unmarshal(data, &raw); err != nil {
569			return fmt.Errorf("parsing pii: %w", err)
570		}
571		if v, ok := raw["enabled"]; ok {
572			if err := json.Unmarshal(v, &dst.Enabled); err != nil {
573				return fmt.Errorf("parsing pii.enabled: %w", err)
574			}
575		}
576		if v, ok := raw["email"]; ok {
577			var b bool
578			if err := json.Unmarshal(v, &b); err != nil {
579				return fmt.Errorf("parsing pii.email: %w", err)
580			}
581			dst.Email = &b
582		}
583		if v, ok := raw["phone"]; ok {
584			var b bool
585			if err := json.Unmarshal(v, &b); err != nil {
586				return fmt.Errorf("parsing pii.phone: %w", err)
587			}
588			dst.Phone = &b
589		}
590		if v, ok := raw["address"]; ok {
591			var b bool
592			if err := json.Unmarshal(v, &b); err != nil {
593				return fmt.Errorf("parsing pii.address: %w", err)
594			}
595			dst.Address = &b
596		}
597		if v, ok := raw["custom_patterns"]; ok {
598			var cp map[string]string
599			if err := json.Unmarshal(v, &cp); err != nil {
600				return fmt.Errorf("parsing pii.custom_patterns: %w", err)
601			}
602			if dst.CustomPatterns == nil {
603				dst.CustomPatterns = cp
604			} else {
605				for k, val := range cp {
606					dst.CustomPatterns[k] = val
607				}
608			}
609		}
610		return nil
611	}
