735	// CheckpointRemoteConfig holds the structured checkpoint remote configuration.
736	// Stored in strategy_options.checkpoint_remote as {"provider": "github", "repo": "org/repo"}.
737	type CheckpointRemoteConfig struct {
738		Provider string // e.g., "github"
