742	// Owner returns the owner portion of the repo field (before the slash).
743	// Returns empty string if the repo field doesn't contain a slash.
744	func (c *CheckpointRemoteConfig) Owner() string {
745		parts := strings.SplitN(c.Repo, "/", 2)
746		if len(parts) < 2 {
747			return ""
748		}
749		return parts[0]
