752	// GetCheckpointRemote returns the configured checkpoint remote.
753	// Expects a structured object: {"provider": "github", "repo": "org/repo"}.
754	// Returns nil if not configured, wrong type, or missing required fields.
755	func (s *EntireSettings) GetCheckpointRemote() *CheckpointRemoteConfig {
756		if s.StrategyOptions == nil {
757			return nil
758		}
759		val, ok := s.StrategyOptions["checkpoint_remote"]
760		if !ok {
761			return nil
762		}
763		m, ok := val.(map[string]any)
764		if !ok {
765			return nil
766		}
767		provider, providerOK := m["provider"].(string)
768		repo, repoOK := m["repo"].(string)
769		if !providerOK || !repoOK || provider == "" || repo == "" {
770			return nil
771		}
772		if !strings.Contains(repo, "/") {
773			return nil
774		}
775		return &CheckpointRemoteConfig{Provider: provider, Repo: repo}
776	}
