791	// CheckpointsVersion returns the configured checkpoints format version from
792	// strategy_options.checkpoints_version. Returns 1 when unset, invalid, or
793	// unsupported. The currently supported versions are 1 and 2.
794	func (s *EntireSettings) CheckpointsVersion() int {
795		if s.StrategyOptions == nil {
796			return 1
797		}
798		val, ok := s.StrategyOptions["checkpoints_version"]
799		if !ok {
800			return 1
801		}
