809	func parseCheckpointsVersion(val any) (int, bool) {
810		v, ok := val.(int)
811		if ok && (v == 1 || v == 2) {
812			return v, true
813		}
814		floatV, ok := val.(float64)
815		if ok && (floatV == 1 || floatV == 2) {
816			return int(floatV), true
817		}
818		stringV, ok := val.(string)
819		if ok {
820			parsed, err := strconv.Atoi(stringV)
821			if err == nil && (parsed == 1 || parsed == 2) {
822				return parsed, true
823			}
824		}
825		return 1, false
826	}
