// NewReviewer returns the AgentReviewer for codex.
//
// Argv shape: codex exec review --json --skip-git-repo-check -.
// Custom review instructions (entire's composed prompt minus /review) are
// piped via stdin. Codex's `exec review` enforces mutual exclusion between
// `--base`/`--uncommitted`/`--commit` and `[PROMPT]`, so we deliberately
// pass NO scope flag — the scope is conveyed inside the prompt as text
// (via the "Scope: ..." clause produced by review.ComposeReviewPrompt).
// This preserves entire's always-prompt / per-run prompt / checkpoint
// context layering, which would be silently dropped if we used flag-mode.
//
// Requires codex CLI >= 0.130.0 — older versions of `codex exec review`
// did not accept a [PROMPT] argument.
func NewReviewer() *reviewtypes.ReviewerTemplate {
	return &reviewtypes.ReviewerTemplate{
		AgentName: "codex",
		BuildCmd:  buildCodexReviewCmd,
		Parser:    parseCodexOutput,
	}
}

// buildCodexReviewCmd builds the exec.Cmd for a codex review run via codex's
// native `exec review` subcommand. Exposed at package level for test
// inspection of argv, stdin, and env.
func buildCodexReviewCmd(ctx context.Context, cfg reviewtypes.RunConfig) *exec.Cmd {
	args := []string{codexExecCommand, "review", "--json", "--skip-git-repo-check", "-"}

	prompt := composeNativeReviewPrompt(cfg)
	cmd := exec.CommandContext(ctx, "codex", args...)
	cmd.Stdin = strings.NewReader(prompt)
	cmd.Env = review.AppendReviewEnv(os.Environ(), "codex", cfg, prompt)
	return cmd
}

