336			for _, hook := range group.Hooks {
337				if !isEntireHook(hook.Command) {
338					filtered = append(filtered, hook)
339				}
340			}
341			if len(filtered) > 0 {
342				group.Hooks = filtered
343				result = append(result, group)
344			}
345		}
346		return result
347	}
348	
349	// configFileName is the Codex config file name.
350	const configFileName = "config.toml"
351	
352	// featureLine is the TOML line that enables the hooks feature. The flag was
353	// renamed from `codex_hooks` to `hooks` in Codex 0.129.0; the old name is
354	// still accepted as a legacy alias but emits a deprecation warning at
355	// every startup. ensureProjectFeatureEnabled rewrites the legacy form when
356	// it sees it.
357	const (
358		featureLine       = "hooks = true"
359		legacyFeatureLine = "codex_hooks = true"
360	)
361	
362	// ensureProjectFeatureEnabled writes features.hooks = true to the
363	// project-level .codex/config.toml. This keeps the feature flag per-repo.
364	// Replaces the deprecated codex_hooks = true line if it's present.
365	func ensureProjectFeatureEnabled(repoRoot string) error {
366		configPath := filepath.Join(repoRoot, ".codex", configFileName)
367	
368		data, err := os.ReadFile(configPath) //nolint:gosec // path constructed from repo root
369		if err != nil && !os.IsNotExist(err) {
370			return fmt.Errorf("failed to read config.toml: %w", err)
371		}
372	
373		content := string(data)
374		hasNew := containsFeatureLine(content, featureLine)
375		hasLegacy := containsFeatureLine(content, legacyFeatureLine)
376		switch {
377		case hasNew && hasLegacy:
378			content = stripLegacyFeatureLine(content)
379		case hasNew:
380			return nil
381		case hasLegacy:
382			content = strings.Replace(content, legacyFeatureLine, featureLine, 1)
383		case strings.Contains(content, "[features]"):
384			content = strings.Replace(content, "[features]", "[features]\n"+featureLine, 1)
385		default:
386			if len(content) > 0 && !strings.HasSuffix(content, "\n") {
387				content += "\n"
388			}
389			content += "\n[features]\n" + featureLine + "\n"
390		}
391	
392		if err := os.MkdirAll(filepath.Dir(configPath), 0o750); err != nil {
393			return fmt.Errorf("failed to create .codex directory: %w", err)
394		}
395		if err := os.WriteFile(configPath, []byte(content), 0o600); err != nil { //nolint:gosec // path constructed from repo root
396			return fmt.Errorf("failed to write config.toml: %w", err)
397		}
398		return nil
399	}
400	
401	// containsFeatureLine checks for an exact line match. A plain
402	// strings.Contains is wrong because "hooks = true" is a substring of
403	// "codex_hooks = true" — without the line-boundary anchor we'd treat the
404	// legacy form as if the new form was already present.
405	func containsFeatureLine(content, line string) bool {
406		for _, raw := range strings.Split(content, "\n") {
407			if strings.TrimSpace(raw) == line {
408				return true
409			}
410		}
411		return false
412	}
413	
414	// stripLegacyFeatureLine removes the deprecated `codex_hooks = true` line
415	// from a TOML config string, dropping a trailing blank line so the file
416	// stays tidy. The new `hooks = true` is added separately by the caller.
417	func stripLegacyFeatureLine(content string) string {
418		idx := strings.Index(content, legacyFeatureLine)
419		if idx < 0 {
420			return content
421		}
422		end := idx + len(legacyFeatureLine)
423		if end < len(content) && content[end] == '\n' {
424			end++
425		}
426		return content[:idx] + content[end:]
427	}
