// NewReviewer returns the AgentReviewer for codex.
//
// Argv shape: codex exec review [--base <ref> | --uncommitted] --json
// --skip-git-repo-check. Scope is carried exclusively by flags — codex's CLI
// rejects combining `--base`/`--uncommitted`/`--commit` with a [PROMPT]
// argument or stdin prompt, and rejects combining `--base` with
// `--uncommitted`. Entire's user-customization (always-prompt, per-run
// prompt, checkpoint context, non-/review skills) is propagated via
// ENTIRE_REVIEW_* env vars (see review.AppendReviewEnv) and re-emitted by
// the user-prompt-submit hook as `hookSpecificOutput.additionalContext`
// so the model sees it.
//
// Requires a codex CLI build that supports `codex exec review`.
func NewReviewer() *reviewtypes.ReviewerTemplate {
	return &reviewtypes.ReviewerTemplate{
		AgentName: "codex",
		BuildCmd:  buildCodexReviewCmd,
		Parser:    parseCodexOutput,
	}
}

// buildCodexReviewCmd builds the exec.Cmd for a codex review run via codex's
// native `exec review` subcommand. Exposed at package level for test
// inspection of argv and env.
//
// Scope flag selection:
//   - cfg.ScopeBaseRef non-empty → "--base <ref>" (committed diff vs base)
//   - cfg.ScopeBaseRef empty     → "--uncommitted" (working-tree only)
//
// We never pass both — codex enforces mutual exclusion. The textual hint
// "Also consider uncommitted working-tree changes if any." is injected via
// the additionalContext hook output when --base is used, preserving the
// "committed + uncommitted" review surface entire's other agents get.
func buildCodexReviewCmd(ctx context.Context, cfg reviewtypes.RunConfig) *exec.Cmd {
	args := []string{codexExecCommand, "review"}
	if cfg.ScopeBaseRef != "" {
		args = append(args, "--base", cfg.ScopeBaseRef)
	} else {
		args = append(args, "--uncommitted")
	}
	args = append(args, "--json", "--skip-git-repo-check")

	cmd := exec.CommandContext(ctx, "codex", args...)
	// Compose the review prompt for downstream metadata (lifecycle hook
	// records it as state.ReviewPrompt). It is NOT passed to codex on argv
	// or stdin — the user-prompt-submit hook re-emits the same data as
	// additionalContext using the ENTIRE_REVIEW_* env vars.
	prompt := review.ComposeReviewPrompt(cfg)
	cmd.Env = review.AppendReviewEnv(os.Environ(), "codex", cfg, prompt)
	return cmd
}

// codexExecCommand is still used by the parser/output_filter chrome-strip
// state machine to detect codex's "exec" tool-call banners; keep it even
// though buildCodexReviewCmd now invokes the `exec review` subcommand.
const codexExecCommand = "exec"

// parseCodexOutput wraps the reader with the chrome filter and converts
// remaining lines into a stream of Events.
// On clean EOF emits Finished{Success: true}. On a scanner error (including
// errors propagated from Strip via pipe CloseWithError) emits RunError then
// Finished{Success: false}.
//
// Exposed for golden-file contract testing.
func parseCodexOutput(r io.Reader) <-chan reviewtypes.Event {
	out := make(chan reviewtypes.Event, 32)
	go func() {
		defer close(out)
		out <- reviewtypes.Started{}
		scanner := bufio.NewScanner(r)
		scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)
		state := codexEventNormal
		for scanner.Scan() {
			for _, ev := range collectCodexEventsLine(scanner.Text(), &state) {
				out <- ev
			}
		}
		if err := scanner.Err(); err != nil {
			out <- reviewtypes.RunError{Err: fmt.Errorf("read stdout: %w", err)}
			out <- reviewtypes.Finished{Success: false}
			return
		}
		out <- reviewtypes.Finished{Success: true}
	}()
	return out
}

type codexEventState int

const (
	codexEventNormal codexEventState = iota
	codexEventUserBlock
	codexEventAssistantBlock
	codexEventExecAwaitCommand
	codexEventExecBlock
	codexEventAfterTokens
)

func collectCodexEventsLine(raw string, state *codexEventState) []reviewtypes.Event {
	cleaned := csiRegex.ReplaceAllString(raw, "")
	trimmed := strings.TrimSpace(cleaned)
	trimmedRight := strings.TrimRight(cleaned, " \t")

	if *state == codexEventAfterTokens {
		return nil
	}
	if isTokensUsedMarker(trimmed) {
		*state = codexEventAfterTokens
		return nil
	}

	switch *state {
