// NewReviewer returns the AgentReviewer for codex.
//
// Argv shape: codex exec --json --skip-git-repo-check -.
// The prompt is piped via stdin verbatim from review.ComposeReviewPrompt:
// skill invocations (including the literal `/review` token) come first,
// followed by always-prompt, per-run prompt, scope clause, and checkpoint
// context — the same layout other agents (claude-code, gemini-cli) get.
//
// Rationale: codex's `exec review` subcommand rejects combining scope flags
// with [PROMPT], and hooks don't fire during non-interactive exec, so the
// native-review subcommand can't carry entire's user customization. But
// codex's runtime auto-loads installed skills from `~/.codex/skills/` when
// the prompt references them — passing `/review` literally lets codex's
// own skill system kick in, matching the behavior a user gets running
// `/review` interactively. We just don't paraphrase `/review` into 28
// words anymore; that paraphrase was the contributor to the speed gap.
func NewReviewer() *reviewtypes.ReviewerTemplate {
	return &reviewtypes.ReviewerTemplate{
		AgentName: "codex",
		BuildCmd:  buildCodexReviewCmd,
		Parser:    parseCodexOutput,
	}
}

// buildCodexReviewCmd builds the exec.Cmd for a codex review run. Exposed
// at package level for test inspection of argv, stdin, and env.
func buildCodexReviewCmd(ctx context.Context, cfg reviewtypes.RunConfig) *exec.Cmd {
	args := []string{codexExecCommand, "--json", "--skip-git-repo-check", "-"}
	prompt := review.ComposeReviewPrompt(cfg)
	cmd := exec.CommandContext(ctx, "codex", args...)
	cmd.Stdin = strings.NewReader(prompt)
	cmd.Env = review.AppendReviewEnv(os.Environ(), "codex", cfg, prompt)
	return cmd
}

// codexExecCommand is used both as the argv subcommand and by the parser /
// output_filter state machine to detect codex's "exec" tool-call banners.
const codexExecCommand = "exec"

