// readCodexCmdStdin drains cmd.Stdin (which buildCodexReviewCmd sets via
// strings.NewReader) so tests can assert on the prompt content piped to
// codex. Fails the test if Stdin is nil.
func readCodexCmdStdin(t *testing.T, cmd *exec.Cmd) string {
	t.Helper()
	if cmd.Stdin == nil {
		t.Fatal("cmd.Stdin is nil")
	}
	b, err := io.ReadAll(cmd.Stdin)
	if err != nil {
		t.Fatalf("read cmd.Stdin: %v", err)
	}
	return string(b)
}

